@font-face {
  font-family: 'StageFont';
  src: url('data:font/otf;base64,') format('opentype');
}

* { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --bg:      #1a1a2e;
  --surface: #16213e;
  --border:  #374151;
  --green:   #8bd42c;
  --blue:    #60a5fa;
  --red:     #f87171;
  --yellow:  #fbbf24;
  --text:    #e2e8f0;
  --dim:     #6b7280;
}

body {
  background-color: var(--bg);
  background-image: url('Pictures/background.png');
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-family: 'StageFont', sans-serif;
  color: var(--text);
}

.content-box {
  background: rgba(26, 26, 46, 0.92);
  padding: 36px 48px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.bc-text {
  color: #FFE000;
  -webkit-text-stroke: 8px #000;
  paint-order: stroke fill;
  font-weight: 900;
  letter-spacing: 3px;
}

h1#title { font-size: 3.5rem; letter-spacing: 6px; margin-bottom: 24px; }

#hud { display: flex; gap: 40px; margin-bottom: 12px; font-size: 1.6rem; letter-spacing: 2px; }
#hud span { color: var(--dim); }
#hud span.pop { color: var(--green); }

#game {
  position: relative;
  width: 800px;
  height: 200px;
  background: var(--surface);
  border: 2px solid var(--border);
  overflow: hidden;
}

#game::before {
  content: '';
  position: absolute;
  bottom: 0; left: 0; right: 0;
  height: 2px;
  background: var(--border);
}

#dino {
  position: absolute;
  bottom: 0; left: 50px;
  width: 40px; height: 40px;
  background: var(--green);
  transition: height 0.05s;
}

.obstacle { position: absolute; width: 30px; }
.obstacle.ground { bottom: 0; background: var(--red); }
.obstacle.flying { background: var(--blue); }

#controls {
  margin-top: 14px;
  font-size: 1.1rem;
  color: var(--dim);
  letter-spacing: 1px;
  display: flex;
  gap: 24px;
  font-family: 'StageFont', sans-serif;
}
#controls span { color: var(--yellow); }

#begin {
  margin-top: 28px;
  padding: 14px 32px;
  font-family: 'StageFont', sans-serif;
  font-size: 1.5rem;
  letter-spacing: 2px;
  background: transparent;
  border: 2px solid #000;
  cursor: pointer;
  transition: all 0.15s;
}
#begin:hover { background: var(--yellow); -webkit-text-stroke: 4px #000; }

#endScreen {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.75);
  justify-content: center;
  align-items: center;
  z-index: 100;
}

.endBox {
  background: var(--surface);
  border: 2px solid var(--red);
  padding: 40px 50px;
  text-align: center;
  min-width: 320px;
  font-family: 'StageFont', sans-serif;
}
.endBox h2 { font-size: 2.8rem; letter-spacing: 3px; margin-bottom: 24px; }
.endBox p { font-size: 1.4rem; margin-bottom: 10px; letter-spacing: 1px; }

#retry {
  margin-top: 24px;
  padding: 12px 28px;
  font-family: 'StageFont', sans-serif;
  font-size: 1.4rem;
  letter-spacing: 2px;
  background: transparent;
  border: 2px solid #000;
  cursor: pointer;
  transition: all 0.15s;
}
#retry:hover { background: var(--yellow); -webkit-text-stroke: 4px #000; }
